import React, { useState } from 'react';

import cn from 'clsx';
import { useNavigate } from 'react-router-dom';

import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import { getGeoRegionsAsync } from '@apps/Routes/@services/geo.services';
import { selectOneRoute } from '@apps/Routes/RoutesList/selectRouteModal';
import { selectGeoRegionOneAsync } from '@components/GeoRegionSelector';
import { selectHikingTypeOneAsync } from '@components/HikingTypeSelector';
import { getColor } from '@helpers/colorsHelper';
import { getSQLDate } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohSelect, { IPohSelectItem } from '@ui-kit/Select';

import { getAllRoutes } from '../../../Routes/@services/routes.service';
import {
  createHikingAsync,
  getHikingTypesAsync,
  updateHikingAsync,
} from '../../@services/hiking.service';
import { IUpdateHikingDTO } from '../../@types/DTO/hiking.dto.types';

const HikingBaseInfoForm = ({ hikingData }: { hikingData?: IHikingData }) => {
  const [regions, setRegions] = useState<IPohSelectItem<number>[]>();
  const [types, setTypes] = useState<IPohSelectItem<number>[]>();
  const [routes, setRoutes] = useState<IPohSelectItem<number>[]>();
  const [formData, setFormData] = useState<IUpdateHikingDTO>({
    id: hikingData?.id ?? 0,
    type: hikingData?.type?.id ?? 1,
    name: hikingData?.name ?? '',
    desc: hikingData?.desc ?? '',
    d1: getSQLDate(hikingData?.start ?? new Date(Date.now() + 86400000 * 7)),
    d2: getSQLDate(hikingData?.finish ?? new Date(Date.now() + 86400000 * 14)),
    id_route: hikingData?.route?.id ?? null,
    id_region: hikingData?.region?.id ?? null,
    color: hikingData?.visual?.color ?? getColor(),
    is_vacant_route: hikingData?.route?.isVacant ?? false,
    allow_join_before: hikingData?.allow_join_before
      ? getSQLDate(hikingData?.allow_join_before)
      : null,
    members_limit: hikingData?.members_limit ?? 0,
  });

  const navigate = useNavigate();

  React.useEffect(() => {
    Promise.all([getGeoRegionsAsync(), getHikingTypesAsync(), getAllRoutes()]).then(
      ([regionsResponse, typesResponse, routesResponse]) => {
        setRegions(regionsResponse.map((x) => ({ value: x.id, label: x.name })));
        setTypes(typesResponse.map((x) => ({ value: x.id, label: x.name })));
        setRoutes(
          routesResponse.map((x) => ({
            value: x.id,
            label: `${x.name} [${formatDistance(+x.distance)}]`,
          })),
        );
      },
    );
  }, []);

  const submitFormHandler = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.is_vacant_route && !formData.id_route) {
      err('Нужно выбрать маршрут или разрешать его выбирать');
      document.getElementById('#new-hiking-route')?.focus();
      return;
    }

    try {
      if (formData.id > 0) {
        const { id, success: msg } = await updateHikingAsync(formData);
        navigate(`/hiking/${id}/edit`);
        success(msg ?? '');
      } else {
        const { id, success: msg } = await createHikingAsync(formData);
        navigate(`/hiking/${id}/edit`);
        success(msg ?? '');
      }
    } catch (er) {
      err((er as Error).message || 'Ошибка');
    }
  };

  const handleInputChange =
    <K extends keyof IUpdateHikingDTO>(field: keyof IUpdateHikingDTO) =>
    (value: IUpdateHikingDTO[K]) => {
      setFormData((fd) => ({
        ...fd,
        [field]: value,
      }));
    };

  return (
    <div>
      <form onSubmit={submitFormHandler} className={cn('mt-4', 'qa-hiking-base-info-form')}>
        <PohRow className="mb-2">
          <PohCol sm={12}>
            <PohInput
              horizontal
              label="Название"
              labelClassName="text-end"
              placeholder="Название похода"
              required
              value={formData.name}
              name="hiking-name"
              id="hiking-name"
              onChange={handleInputChange('name')}
              autoComplete="hiking-name"
              autoFocus
            />
          </PohCol>
        </PohRow>
        <PohRow className="mb-2">
          <PohCol sm={12}>
            <PohInput
              horizontal
              type={InputTypes.textarea}
              label="Описание"
              placeholder="Краткое описание похода (тизер)"
              required
              value={formData.desc}
              name="hiking-desc"
              id="hiking-desc"
              onChange={handleInputChange('desc')}
              labelClassName="text-end"
            />
          </PohCol>
        </PohRow>
        <PohRow className="mb-4">
          <PohCol sm={2} className="text-end">
            Даты
          </PohCol>
          <PohCol sm={10}>
            <PohRow>
              <PohCol sm={6}>
                <PohInput
                  type={InputTypes.datetimeLocal}
                  required
                  max={formData.d2.substr(0, 16).replace(' ', 'T')}
                  value={formData.d1.substr(0, 16).replace(' ', 'T')}
                  onChange={(v) => handleInputChange('d1')(getSQLDate(new Date(v ?? '')))}
                />
              </PohCol>
              <PohCol sm={6}>
                <PohInput
                  type={InputTypes.datetimeLocal}
                  required
                  min={formData.d1.substr(0, 16).replace(' ', 'T')}
                  value={formData.d2.substr(0, 16).replace(' ', 'T')}
                  onChange={(v) => handleInputChange('d2')(getSQLDate(new Date(v ?? '')))}
                />
              </PohCol>
            </PohRow>
          </PohCol>
        </PohRow>
        <PohRow className="mb-4">
          <PohCol sm={2} className="text-end">
            Ограничения
          </PohCol>
          <PohCol sm={10}>
            <PohRow>
              <PohCol sm={6}>
                <PohInput
                  label="Разрешить присоединяться до"
                  placeholder="Не задано"
                  type={InputTypes.datetimeLocal}
                  max={formData.d1.substr(0, 16).replace(' ', 'T')}
                  value={formData.allow_join_before?.substr(0, 16).replace(' ', 'T')}
                  onChange={(v) =>
                    handleInputChange('allow_join_before')(v ? `${v.replace('T', ' ')}:00` : null)
                  }
                />
              </PohCol>
              <PohCol sm={6}>
                <PohInput
                  type={InputTypes.number}
                  label="Кол-во участников"
                  placeholder="Не ограничено"
                  min={0}
                  max={999}
                  value={formData.members_limit ? formData.members_limit.toString() : ''}
                  onChange={(v) => handleInputChange('members_limit')(v)}
                />
              </PohCol>
            </PohRow>
          </PohCol>
        </PohRow>
        <PohRow className="mb-2">
          <PohCol sm={12}>
            <div className="d-flex align-items-center ms-2">
              <PohSelect
                horizontal
                options={types || []}
                disabled={!types}
                label="Тип"
                placeholder="тип не выбран"
                required
                value={formData.type}
                onChange={(v) => handleInputChange('type')(v || null)}
                wrapperClassName="flex-grow-1 text-end"
              />
              <PohButton
                icon={IconsEnum.search}
                className=" ms-2"
                onClick={async () => {
                  const sel = await selectHikingTypeOneAsync({});
                  handleInputChange('type')(sel?.id ?? null);
                }}
              />
            </div>
          </PohCol>
        </PohRow>
        <PohRow className="mb-2">
          <PohCol sm={12}>
            <div className="d-flex align-items-center ms-2">
              <PohSelect
                horizontal
                options={regions || []}
                label="Регион"
                placeholder="регион не выбран"
                required
                allowEmpty
                value={formData.id_region}
                onChange={handleInputChange('id_region')}
                disabled={!regions}
                wrapperClassName="flex-grow-1 text-end"
              />
              <PohButton
                icon={IconsEnum.search}
                className=" ms-2"
                onClick={async () => {
                  const sel = await selectGeoRegionOneAsync({});
                  handleInputChange('id_region')(sel?.id ?? null);
                }}
              />
            </div>
          </PohCol>
        </PohRow>
        <PohRow className="d-flex align-items-center mb-1">
          <PohCol sm={12}>
            <div className="d-flex align-items-center ms-2">
              <PohSelect
                horizontal
                options={routes || []}
                label="Маршрут"
                placeholder="маршрут не выбран"
                value={formData.id_route}
                id="new-hiking-route"
                disabled={!routes}
                allowEmpty
                onChange={handleInputChange('id_route')}
                wrapperClassName="flex-grow-1 text-end"
              />
              <PohButton
                icon={IconsEnum.search}
                className=" ms-2"
                onClick={async () => {
                  const sel = await selectOneRoute();
                  handleInputChange('id_route')(sel?.id ?? null);
                }}
              />
            </div>
          </PohCol>
        </PohRow>
        <PohRow className="mb-4">
          <PohCol sm={2} />
          <PohCol sm={10}>
            <PohCheckbox
              label="Разрешить предлагать"
              checked={formData.is_vacant_route}
              onChange={handleInputChange<'is_vacant_route'>('is_vacant_route')}
            />
          </PohCol>
        </PohRow>
        <PohRow className="mb-4 mt-2">
          <PohCol sm={2} />
          <PohCol sm={10}>
            <PohButton
              variant={ButtonVariant.Primary}
              onClick={() => {}}
              className="w-100"
              type="submit"
            >
              {hikingData ? 'Сохранить' : 'Добавить'}
            </PohButton>
          </PohCol>
        </PohRow>
      </form>
    </div>
  );
};

export default HikingBaseInfoForm;
